// Checks the built project pages (dist/projects/<id>/index.html) generated by
// src/pages/projects/[slug].astro against the Markdown files in
// src/content/projects: one page per entry, head metadata, header, repo link,
// rendered body, back links, hydration, sidebar menu and the /website/ base.
// It reads the build output and never builds; `npm test` builds first.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readdirSync, readFileSync } from 'node:fs';

const BASE = '/website/';
const contentDir = new URL('../src/content/projects/', import.meta.url);
const distProjects = new URL('../dist/projects/', import.meta.url);
assert.ok(existsSync(distProjects), 'dist/projects not found: run `astro build` (or `npm test`) first');

/** Splits a Markdown file into flat `key: value` frontmatter and body. */
function parseMarkdown(text) {
  const [, front, body] = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  const data = {};
  for (const line of front.split(/\r?\n/)) {
    const m = line.match(/^(\w+):\s*(.*)$/);
    if (!m) continue;
    const value = m[2].trim();
    data[m[1]] = value.startsWith('[')
      ? value.slice(1, -1).split(',').map((s) => unquote(s.trim())).filter(Boolean)
      : unquote(value);
  }
  data.order = Number(data.order);
  return { data, body };
}

function unquote(s) {
  return s.replace(/^(['"])(.*)\1$/, '$2');
}

function escapeHtml(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/** React's server renderer also escapes `'`, so use this for markup ProjectDetail renders. */
function escapeReact(s) {
  return escapeHtml(s).replace(/'/g, '&#x27;');
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const projects = readdirSync(contentDir)
  .filter((name) => name.endsWith('.md'))
  .map((name) => {
    const { data, body } = parseMarkdown(readFileSync(new URL(name, contentDir), 'utf8'));
    return { id: name.slice(0, -3), ...data, body };
  });
const byOrder = [...projects].sort((a, b) => a.order - b.order);

function page(id) {
  return readFileSync(new URL(`${id}/index.html`, distProjects), 'utf8');
}

function header(html) {
  return html.match(/<header class="page-header container">([\s\S]*?)<\/header>/)?.[1] ?? '';
}

function prose(html) {
  return html.match(/<div class="prose">([\s\S]*?)<\/div><a class="back-link"/)?.[1] ?? '';
}

test('the content folder has projects to check', () => {
  assert.ok(projects.length > 0);
});

test('one built page per collection entry and no others', () => {
  const built = readdirSync(distProjects, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
    .sort();
  assert.deepEqual(built, projects.map((p) => p.id).sort());
  for (const { id } of projects) {
    assert.ok(existsSync(new URL(`${id}/index.html`, distProjects)), `no page for ${id}`);
  }
});

for (const project of projects) {
  const { id, title, summary, tags, repo, body } = project;

  test(`${id}: title and meta description`, () => {
    const html = page(id);
    assert.match(html, new RegExp(`<title>${escapeRegex(escapeHtml(title))} · Benjamin Warring</title>`));
    assert.ok(
      html.includes(`<meta name="description" content="${escapeHtml(summary)}">`),
      `meta description for ${id}`,
    );
  });

  test(`${id}: h1, lead and tags in the page header`, () => {
    const head = header(page(id));
    assert.ok(head.includes(`<h1>${escapeReact(title)}</h1>`), `h1 for ${id}`);
    assert.ok(head.includes(`<p class="lead">${escapeReact(summary)}</p>`), `lead for ${id}`);
    const tagItems = tags.map((t) => `<li class="tag">${escapeReact(t)}</li>`).join('');
    assert.ok(head.includes(`<ul class="tags" aria-label="Technologies">${tagItems}</ul>`), `tags for ${id}`);
  });

  test(`${id}: header links go to the repo and to all projects`, () => {
    const links = [...header(page(id)).matchAll(/<a href="([^"]*)">([^<]*)<\/a>/g)].map((m) => [m[2], m[1]]);
    const expected = repo ? [['View on GitHub', escapeReact(repo)]] : [];
    expected.push(['All projects', `${BASE}projects/`]);
    assert.deepEqual(links, expected);
  });

  test(`${id}: Markdown headings are rendered inside .prose`, () => {
    const html = page(id);
    const rendered = prose(html);
    const headings = [...body.matchAll(/^(#{1,6})\s+(.+?)\s*$/gm)].map((m) => [m[1].length, m[2]]);
    assert.ok(headings.length > 0, `${id}.md has no headings`);
    for (const [level, text] of headings) {
      assert.match(rendered, new RegExp(`<h${level}[^>]*>${escapeRegex(escapeHtml(text))}</h${level}>`));
    }
    assert.ok(!header(html).includes('<h2'), 'body headings leaked into the page header');
  });

  test(`${id}: back link points to all projects`, () => {
    assert.ok(page(id).includes(`<a class="back-link" href="${BASE}projects/">Back to all projects</a>`));
  });

  test(`${id}: ProjectDetail is hydrated on load`, () => {
    assert.match(
      page(id),
      /<astro-island\b[^>]*component-url="\/website\/_astro\/ProjectDetail\.[^"]+\.js"[^>]*\sclient="load"/,
    );
  });

  test(`${id}: sidebar lists every project in order and highlights this one`, () => {
    const html = page(id);
    const labels = [...html.matchAll(/branched-menu__label">([^<]*)</g)].map((m) => m[1]);
    const projectLabels = labels.slice(labels.indexOf('All projects') + 1);
    assert.deepEqual(projectLabels, byOrder.map((p) => escapeReact(p.title)));
    const current = [...html.matchAll(/aria-current="true"[^>]*>[\s\S]*?branched-menu__label">([^<]*)</g)];
    assert.deepEqual(current.map((m) => m[1]), [escapeReact(title)]);
  });

  test(`${id}: every internal link keeps the /website/ base`, () => {
    const html = page(id);
    assert.doesNotMatch(html, /(?:href|src|component-url|renderer-url)="\/(?!website\/)/);
    assert.doesNotMatch(html, /(?:href|src)="(?!https?:|mailto:|#|\/)/, 'relative URL found');
  });
}
